  function readCart() { try { const a=JSON.parse(localStorage.getItem('taj_cart_v1')||'[]'); return Array.isArray(a)?a.filter(x=>x&&Number.isInteger(Number(x.id))&&Number(x.qty)>0).map(x=>({id:Number(x.id),qty:Number(x.qty)})):[]; } catch { return []; } }
