  function initReveal(root) {
    const targets=[...root.querySelectorAll('[data-reveal]')];
    if(!targets.length)return;
    if(!('IntersectionObserver' in window)){targets.forEach(el=>el.classList.add('is-revealed'));return;}
    root.classList.add('reveal-ready');
    const observer=new IntersectionObserver((entries,watcher)=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('is-revealed');watcher.unobserve(entry.target);}}},{threshold:.14,rootMargin:'0px 0px -36px 0px'});
    targets.forEach(el=>observer.observe(el));
  }
  async function renderHome(view) {
    updateTitle('Home','Taj Opticals in Coimbatore — eyeglasses, sunglasses, contact lenses and optical accessories.');
    const [page,banners,featuredPage]=await Promise.all([api('/api/products?limit=8&sort=newest'),api('/api/banners'),api('/api/products?limit=8&sort=newest&featured=true')]);
    const products=page.products||[];const featured=featuredPage.products||[];const highlighted=featured.length?featured.slice(0,4):products.slice(0,4);
    const videoProduct=products.find(p=>(p.media||[]).some(m=>m.kind==='video'));
    const videoMedia=videoProduct?.media?.find(m=>m.kind==='video');
    const promoted=banners.length?`<section class="wrap"><div class="promo-strip">${banners[0].image_url?`<img class="promo-strip__image" src="${esc(banners[0].image_url)}" alt="" loading="lazy">`:''}<div class="promo-strip__content"><p class="eyebrow" style="color:#b6d2ff">TAJ OPTICALS · PROMOTION</p><h3>${esc(banners[0].headline)}</h3><p>${esc(banners[0].description)}</p><a class="btn btn--small" data-link href="${banners[0].product_id?`/product/${banners[0].product_id}`:'/shop'}">${esc(banners[0].cta_text||'Shop now')} ${icon('arrow')}</a></div></div></section>`:'';
    view.innerHTML=`<section class="hero"><div class="hero__photo" role="img" aria-label="People wearing modern eyeglasses and sunglasses"></div><div class="wrap hero__inner"><div class="hero__copy"><p class="eyebrow hero__eyebrow">WELCOME TO TAJ OPTICALS</p><h1>See the World<span>More Clearly</span></h1><p class="hero__sub">Stylish frames. Clear vision. A better you.</p><a class="btn hero__shop" data-link href="/shop">Shop Now ${icon('arrow')}</a></div><div class="hero__note" aria-hidden="true">Better Vision<br>Brighter Life</div><div class="hero__dots" aria-hidden="true"><span></span><span></span><span></span></div></div></section>${homeAboutSection()}${categoryTiles()}${promoted}<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">${featured.length?'FEATURED PRODUCTS':'LATEST PRODUCTS'}</p><h2>Our <span>${featured.length?'Featured Collection':'Latest Collection'}</span></h2></div><a class="text-link section-head__right" data-link href="/shop">View all products ${icon('arrow')}</a></div>${highlighted.length?`<div class="featured-grid">${highlighted.map((p,i)=>productCard(p,p.featured?'Featured':(i===0?'New':''))).join('')}</div>`:emptyCatalogue()}</div></section>${videoProduct&&videoMedia?`<section class="section section--tight"><div class="wrap"><div class="section-head"><div><p class="eyebrow">PRODUCT VIDEO</p><h2>See it in <span>motion</span></h2></div><a class="text-link" data-link href="/product/${encodeURIComponent(videoProduct.slug)}">View product ${icon('arrow')}</a></div><div class="promo-strip" style="padding:16px;min-height:0;gap:20px"><video controls playsinline preload="none" style="width:min(440px,48%);max-height:260px;border-radius:12px;background:#08172c" src="${esc(videoMedia.url)}"></video><div class="promo-strip__content"><h3>${esc(videoProduct.name)}</h3><p>Product video from the live catalogue.</p><p style="margin-top:9px;font-weight:750;color:#fff">${formatPaise(videoProduct.selling_price_paise)}</p></div></div></div></section>`:''}<section class="store-band"><div class="wrap store-band__inner"><div><p class="eyebrow">FIND US IN COIMBATORE</p><h2>Visit Taj Opticals</h2><p>Come by the store for current product availability and ordering details.</p><div class="store-band__details"><span>${icon('location')}${esc(state.store?.address||'18/109, Channa Complex, Big Bazaar Street, Coimbatore, Tamil Nadu – 641001, India.')}</span><span>${icon('phone')}Call ${esc(state.store?.contact_phone||'9597378385')}</span></div></div><div class="store-band__actions"><a class="btn btn--light" href="${esc(state.store?.maps_url||'https://maps.google.com/?q=10.993682,76.964188')}" target="_blank" rel="noopener noreferrer">Get directions ${icon('arrow')}</a>${state.store?.whatsapp_ready?`<a class="btn" href="https://wa.me/${esc(state.store.whatsapp_number)}" target="_blank" rel="noopener noreferrer">${icon('whatsapp')} WhatsApp us</a>`:`<a class="btn" href="tel:${esc(state.store?.contact_phone||'9597378385')}">${icon('phone')} Call the store</a>`}</div></div></section>`;
    initReveal(view);
  }
  function pagination(page,pages) {
    if(pages<=1)return '';
    const nums=[];for(let i=1;i<=pages;i++){if(i===1||i===pages||Math.abs(i-page)<=1)nums.push(i);else if(nums[nums.length-1]!=='…')nums.push('…');}
    return `<nav class="pagination" aria-label="Product pages"><button data-action="page" data-page="${page-1}" ${page<=1?'disabled':''} aria-label="Previous page">‹</button>${nums.map(n=>n==='…'?`<span style="padding:8px;color:#8994a6">…</span>`:`<button class="${n===page?'is-active':''}" data-action="page" data-page="${n}">${n}</button>`).join('')}<button data-action="page" data-page="${page+1}" ${page>=pages?'disabled':''} aria-label="Next page">›</button></nav>`;
  }
  async function renderListing(view, opts={}) {
    const params=new URLSearchParams(location.search);
    const categorySlug=opts.category||'';
    const category=state.categories.find(c=>c.slug===categorySlug);
    const search=opts.search ?? (params.get('q')||'');
    const page=Math.max(1,Number(params.get('page')||1));
    const apiParams=new URLSearchParams({page:String(page),limit:'12',sort:params.get('sort')||'newest'});
    if(categorySlug)apiParams.set('category',categorySlug);
    if(search)apiParams.set('q',search);
    if(params.get('brand'))apiParams.set('brand',params.get('brand'));
    if(params.get('min_price'))apiParams.set('min_price',params.get('min_price'));
    if(params.get('max_price'))apiParams.set('max_price',params.get('max_price'));
    const [data,brands]=await Promise.all([api('/api/products?'+apiParams.toString()),api('/api/brands')]);
    const title=opts.title||(category?.name|| (search?'Search results':'Shop all'));
    updateTitle(title,search?`Search results for ${search} at Taj Opticals.`:`Browse ${title.toLowerCase()} at Taj Opticals in Coimbatore.`);
    const desc=search?`Results for “${search}” from the live Taj Opticals catalogue.`:(category?`Browse the ${category.name.toLowerCase()} collection from Taj Opticals.`:'Explore the live Taj Opticals catalogue.');
    const filterBar=`<form class="filters" id="catalog-filters"><select class="select" name="brand"><option value="">All brands</option>${brands.map(b=>`<option value="${esc(b.name)}" ${params.get('brand')===b.name?'selected':''}>${esc(b.name)}</option>`).join('')}</select><div class="filter-group"><input class="field field--compact" name="min_price" inputmode="decimal" placeholder="Min ₹" value="${esc(params.get('min_price')||'')}"><span>to</span><input class="field field--compact" name="max_price" inputmode="decimal" placeholder="Max ₹" value="${esc(params.get('max_price')||'')}"></div><select class="select" name="sort"><option value="newest" ${!params.get('sort')||params.get('sort')==='newest'?'selected':''}>Newest</option><option value="price_asc" ${params.get('sort')==='price_asc'?'selected':''}>Price: low to high</option><option value="price_desc" ${params.get('sort')==='price_desc'?'selected':''}>Price: high to low</option><option value="name" ${params.get('sort')==='name'?'selected':''}>Name</option></select><button class="btn btn--small">Apply filters</button></form>`;
    const productBody=data.products.length?`<div class="featured-grid">${data.products.map((p,i)=>productCard(p,i===0?'New':'')).join('')}</div>${pagination(data.page,data.pages)}`:emptyCatalogue();
    view.innerHTML=`${pageHero(title,desc)}<section class="catalog"><div class="wrap"><div class="catalog__bar"><div class="catalog__count">${data.total?`${data.total} ${data.total===1?'product':'products'} in the live catalogue`:'No products found'}</div>${filterBar}</div>${productBody}</div></section>`;
  }
  async function renderProduct(view, slug) {
    const product=await api('/api/products/'+encodeURIComponent(slug));state.currentProduct=product;state.productQty=1;
    let related=[];if(product.category?.slug){try{const relatedPage=await api(`/api/products?category=${encodeURIComponent(product.category.slug)}&limit=5&sort=newest`);related=(relatedPage.products||[]).filter(x=>x.id!==product.id).slice(0,4);}catch{}}
    updateTitle(product.name,product.description||`${product.name} at Taj Opticals.`);
    const imgs=(product.media||[]).filter(m=>m.kind==='image');const vids=(product.media||[]).filter(m=>m.kind==='video');const gallery=[...imgs,...vids];
    const cover=imgs.find(m=>m.is_cover)||imgs[0];const main=cover||vids[0];
    const galleryMain=main?(main.kind==='video'?`<video controls playsinline preload="metadata" src="${esc(main.url)}"></video>`:`<img src="${esc(main.url)}" alt="${esc(product.name)}">`):`<div class="product-card__fallback">${icon('glasses')}</div>`;
    const attrRows=[['Brand',product.brand],['Colour',product.color],['Frame shape',product.frame_shape],['Frame size',product.frame_size],['Material',product.material],...Object.entries(product.specifications||{}).map(([k,v])=>[k.replaceAll('_',' '),v])].filter(x=>x[1]);
    const deliveryCharge=state.store?.delivery?.standard_delivery_charge_paise??5000;
    const stock=product.stock_qty>0&&product.status==='active';
    view.innerHTML=`<section class="page-hero"><div class="wrap"><div class="breadcrumbs"><a data-link href="/">Home</a><span>›</span><a data-link href="/shop">Shop</a><span>›</span><span>${esc(product.name)}</span></div><p class="eyebrow">${esc(product.category?.name||'TAJ OPTICALS')}</p><h1 style="font-size:26px">${esc(product.name)}</h1></div></section><section class="product-detail"><div class="wrap product-detail__grid"><div><div class="gallery__main" id="gallery-main">${galleryMain}</div>${gallery.length>1?`<div class="gallery__thumbs">${gallery.map((m,i)=>`<button class="gallery__thumb ${m.id===main?.id?'is-selected':''}" data-action="gallery-select" data-index="${i}" aria-label="View product media ${i+1}">${m.kind==='video'?`<video muted preload="metadata" src="${esc(m.url)}#t=0.2"></video>`:`<img src="${esc(m.url)}" alt="">`}</button>`).join('')}</div>`:''}</div><div class="product-detail__info"><p class="eyebrow">${esc(product.category?.name||'OPTICAL COLLECTION')}</p><h1>${esc(product.name)}</h1><div class="product-detail__sku">SKU: ${esc(product.sku)}${product.brand?` · ${esc(product.brand)}`:''}</div><span class="stock-pill ${stock?'':'stock-pill--out'}">${stock?`${product.stock_qty} available`:'Currently out of stock'}</span><div class="product-detail__price">${formatPaise(product.selling_price_paise)}${product.original_price_paise?` <del>${formatPaise(product.original_price_paise)}</del>`:''}</div>${product.description?`<p class="product-detail__desc">${esc(product.description)}</p>`:''}${attrRows.length?`<div class="spec-list">${attrRows.map(([k,v])=>`<div class="spec-row"><span>${esc(k)}</span><span>${esc(v)}</span></div>`).join('')}</div>`:''}<div class="notice">${state.store?.delivery?.free_delivery_threshold_paise?`Free delivery on product subtotals of ${formatPaise(state.store.delivery.free_delivery_threshold_paise)} or more. Below that, delivery is ${formatPaise(deliveryCharge)}.`:`Delivery charges apply as shown at checkout.`}</div><div class="quantity-row"><strong style="font-size:12px">Quantity</strong><div class="qty-control"><button data-action="product-qty" data-delta="-1" aria-label="Decrease quantity">−</button><span id="product-qty">1</span><button data-action="product-qty" data-delta="1" aria-label="Increase quantity" ${stock?'':'disabled'}>+</button></div></div><div class="detail-actions"><button class="btn" data-action="add-cart" data-product="${product.id}" ${stock?'':'disabled'}>Add to cart</button><button class="btn btn--outline" data-action="order-product" data-product="${product.id}" ${stock?'':'disabled'}>${icon('whatsapp')} Order via WhatsApp</button></div>${state.store?.whatsapp_ready?`<p class="form-hint">You’ll review a priced order enquiry first. You must press Send in WhatsApp; the store will confirm availability and the order.</p>`:`<div class="notice notice--warning">WhatsApp ordering is ready once the owner verifies a WhatsApp number in admin settings. Call ${esc(state.store?.contact_phone||'9597378385')} meanwhile.</div>`}<p class="form-hint">Prices and stock are sourced from the live catalogue. No online payment is collected here.</p></div></div></section>${related.length?`<section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">YOU MAY ALSO LIKE</p><h2>Related <span>${esc(product.category?.name||'products')}</span></h2></div><a class="text-link" data-link href="/category/${encodeURIComponent(product.category.slug)}">View collection ${icon('arrow')}</a></div><div class="featured-grid">${related.map(p=>productCard(p,'')).join('')}</div></div></section>`:''}`;
    state._gallery=gallery;
  }
  async function renderCart(view) {
    updateTitle('Shopping Cart','Review your cart and send a WhatsApp order enquiry to Taj Opticals.');
    if(!state.cart.length){view.innerHTML=`${pageHero('Your cart','Your selected items will appear here.')}<section class="catalog"><div class="wrap">${emptyCart()}</div></section>`;return;}
    let quote;
    try{quote=await api('/api/quote',{method:'POST',body:{items:cartItemsForApi()}});}catch(e){view.innerHTML=`${pageHero('Your cart','Review your selected products.')}<section class="catalog"><div class="wrap"><div class="notice notice--danger">${esc(e.message)} Please remove unavailable items or refresh product availability.</div><div class="cart-layout"><div class="cart-list">${state.cart.map(i=>`<div class="cart-line"><div class="cart-line__image">${icon('glasses')}</div><div><h3>Catalogue item #${i.id}</h3><p>Live stock or pricing needs to be refreshed.</p><a class="text-link" data-link href="/product/${i.id}">Check item ${icon('arrow')}</a></div><div class="cart-line__end"><button class="cart-line__remove" data-action="cart-remove" data-id="${i.id}">Remove</button></div></div>`).join('')}</div></div></div></section>`;return;}
    if(!quote.items.length){view.innerHTML=`${pageHero('Your cart','Your selected items will appear here.')}<section class="catalog"><div class="wrap">${emptyCart()}</div></section>`;return;}
    view.innerHTML=`${pageHero('Your cart','Review your selected products and current delivery charge.')}<section class="wrap cart-layout"><div class="cart-list">${quote.items.map(line=>`<article class="cart-line"><div class="cart-line__image">${line.image_url?`<img src="${esc(line.image_url)}" alt="${esc(line.name)}">`:icon('glasses')}</div><div><h3><a data-link href="${esc(line.url)}">${esc(line.name)}</a></h3><p>SKU ${esc(line.sku)} · ${formatPaise(line.unit_price_paise)} each</p><div class="qty-control"><button data-action="cart-qty" data-id="${line.product_id}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${line.quantity}</span><button data-action="cart-qty" data-id="${line.product_id}" data-delta="1" aria-label="Increase quantity">+</button></div></div><div class="cart-line__end"><div class="cart-line__price">${formatPaise(line.line_subtotal_paise)}</div><button class="cart-line__remove" data-action="cart-remove" data-id="${line.product_id}">Remove</button></div></article>`).join('')}</div><aside class="cart-summary"><h2>Order summary</h2><div class="summary-row"><span>Product subtotal</span><strong>${formatPaise(quote.product_subtotal_paise)}</strong></div><div class="summary-row"><span>Delivery</span><strong>${quote.delivery_charge_paise===0&&quote.product_subtotal_paise>0?'FREE DELIVERY':formatPaise(quote.delivery_charge_paise)}</strong></div>${quote.product_subtotal_paise>0?`<div class="progress-track"><span style="width:${Math.min(100,quote.product_subtotal_paise/quote.free_delivery_threshold_paise*100)}%"></span></div><p class="cart-summary__message ${quote.free_delivery?'':'notice--none'}">${quote.free_delivery?'Congratulations! You have unlocked FREE DELIVERY.':`Add ${formatPaise(quote.remaining_for_free_delivery_paise)} more to unlock FREE DELIVERY!`}</p>`:''}<div class="summary-row summary-row--total"><span>Final payable total</span><strong>${formatPaise(quote.total_paise)}</strong></div><p class="form-hint">Delivery is ${formatPaise(state.store?.delivery?.standard_delivery_charge_paise??5000)} below ${formatPaise(quote.free_delivery_threshold_paise)} and free at or above the threshold.</p>${state.store?.whatsapp_ready?`<button class="btn" data-action="order-cart">Review WhatsApp order ${icon('arrow')}</button>`:`<button class="btn is-disabled" disabled>WhatsApp number not verified</button><div class="notice notice--warning">WhatsApp ordering is not active yet. Call ${esc(state.store?.contact_phone||'9597378385')} or contact the store.</div>`}<a class="btn btn--light" data-link href="/shop">Continue shopping</a><p class="form-hint">This creates a message draft only. Press Send in WhatsApp; Taj Opticals will confirm the order. No online payment is collected.</p></aside></section>`;
  }
  function emptyCart(){return `<div class="empty-state"><div class="empty-state__icon">${icon('cart')}</div><h3>Your cart is waiting</h3><p>Add a product from the live catalogue, then review its current price, stock and delivery charge here.</p><a class="btn" data-link href="/shop">Explore the catalogue ${icon('arrow')}</a></div>`;}
