  function csvPreviewMarkup(data){
    const errors=data.errors||[];
    return `<div class="notice ${errors.length?'notice--warning':'notice--success'}"><strong>Preview:</strong> ${data.valid_count} valid row(s), ${data.error_count} row error(s). Review this before importing.</div>${data.preview?.length?`<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CSV row</th><th>SKU</th><th>Product</th><th>Category</th><th>Price</th><th>Status</th></tr></thead><tbody>${data.preview.map(r=>`<tr><td>${r.row}</td><td>${esc(r.sku)}</td><td>${esc(r.name)}</td><td>${esc(r.category)}</td><td>${formatPaise(r.price_paise)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`:''}${errors.length?`<div class="csv-errors" style="margin-top:11px"><strong>Row-level errors</strong>${errors.slice(0,60).map(e=>`<p>Row ${e.row}${e.sku?` · ${esc(e.sku)}`:''}: ${esc(e.message)}</p>`).join('')}${errors.length>60?`<p>Showing first 60 of ${errors.length} errors.</p>`:''}</div>`:''}${data.valid_count?`<div class="form-actions"><button class="btn" data-action="csv-commit">Import ${data.valid_count} valid row(s)</button><span class="form-hint">Invalid rows will remain in the error report.</span></div>`:''}`;
  }
