    panel.innerHTML=`<div class="admin-panel__head"><div><h2>Store settings</h2><p>Public business information, WhatsApp confirmation and delivery rules.</p></div></div><form id="store-settings-form" class="form-grid"><div class="form-field"><label>Business name</label><input name="business_name" required maxlength="120" value="${esc(s.business_name)}"></div><div class="form-field"><label>Tagline</label><input name="tagline" maxlength="240" value="${esc(s.tagline)}"></div><div class="form-field form-field--wide"><label>Address</label><input name="address" required maxlength="500" value="${esc(s.address)}"></div><div class="form-field"><label>Google Maps link</label><input name="maps_url" type="url" required value="${esc(s.maps_url)}"><span class="form-hint">The default is the supplied Coimbatore map pin.</span></div><div class="form-field"><label>Business phone (calls)</label><input name="contact_phone" maxlength="40" value="${esc(s.contact_phone)}"></div><div class="form-field"><label>WhatsApp number (international format)</label><input name="whatsapp_number" inputmode="tel" placeholder="e.g. 919597373835" value="${esc(s.whatsapp_number||'')}"><span class="form-hint">Do not enter the number until you have confirmed it is registered on WhatsApp. Use country code, digits only.</span></div><label class="check-field form-field--wide"><input name="whatsapp_verified" type="checkbox" ${s.whatsapp_verified?'checked':''}> I confirm the number above is active on WhatsApp and may receive customer order enquiries.</label><div class="form-field"><label>Free-delivery threshold (₹)</label><input name="free_delivery_threshold_inr" type="number" min="1" step="0.01" required value="${(Number(s.free_delivery_threshold_paise??170000)/100).toFixed(2)}"></div><div class="form-field"><label>Standard delivery charge (₹)</label><input name="standard_delivery_charge_inr" type="number" min="0" step="0.01" required value="${(Number(s.standard_delivery_charge_paise??5000)/100).toFixed(2)}"></div><div class="form-field"><label>Upload brand logo (optional)</label><input id="logo-file" type="file" accept="image/jpeg,image/png,image/webp"><span class="form-hint">For a sharper result, use a transparent PNG or WebP.</span></div><div class="form-field"><label>Logo image URL</label><input name="logo_url" value="${esc(s.logo_url||'')}" placeholder="Uploaded logo URL"><span class="form-hint">Leave blank to use the built-in Taj glasses wordmark.</span></div><div class="form-actions form-field--wide"><button class="btn">Save store settings</button><span class="form-hint">Current defaults: ₹50 delivery below ₹1,700; free at or above ₹1,700.</span></div></form><div class="subsection"><h3>Change admin password</h3><form id="admin-password-form" class="form-grid"><div class="form-field"><label>Current password</label><input name="current_password" type="password" autocomplete="current-password" required></div><div class="form-field"><label>New password (12+ characters)</label><input name="new_password" type="password" autocomplete="new-password" minlength="12" required></div><div class="form-field"><label>Confirm new password</label><input name="confirm_password" type="password" autocomplete="new-password" minlength="12" required></div><div class="form-actions form-field--wide"><button class="btn btn--light btn--small">Update password</button></div></form></div><div class="notice notice--warning" style="margin-top:15px">The business phone ${esc(s.contact_phone||'9597378385')} is configured for calls. WhatsApp ordering stays hidden until the owner verifies a WhatsApp number above.</div>`;
